#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Cutover: the Share modal moves from calling TinyURL directly (with a key baked into the
# bundle) to the sw-shortlink worker at spacewalk.aidenlab.org/shorten. Run from the repo
# root: bash workers/sw-shortlink/cutover-wizard.sh
#
# Order matters: the new key goes on the worker first and is checked with curl; the old key
# is revoked only once the client change is merged. Revoking it breaks nothing either way:
# TinyURL refuses browser calls, so the old key has been dead weight since September 2026.

TOTAL_STAGES=7
WORKER_DIR="workers/sw-shortlink"
SHORTEN="https://spacewalk.aidenlab.org/shorten"

banner "Spacewalk share-URL shortener cutover"

# ──────────────────────────────────────────────────────────────────────────
stage "Cloudflare: sign in to wrangler"
say "The worker deploys to the Cloudflare account that holds the aidenlab.org zone"
say "(the same account as juicebox's jb-shortlink)."
if (cd "$WORKER_DIR" && npx wrangler whoami 2>/dev/null | grep -qi "logged in"); then
  printf '  %s✓%s wrangler is signed in:\n' "$GREEN" "$RESET"
  (cd "$WORKER_DIR" && npx wrangler whoami 2>/dev/null | grep -i -E "logged in|account" | sed 's/^/    /') || true
else
  step "wrangler is not signed in. A browser window will open for the Cloudflare login."
  pause "Press Enter to run wrangler login"
  (cd "$WORKER_DIR" && npx wrangler login)
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Cloudflare: deploy sw-shortlink"
say "Deploys the worker and claims the route spacewalk.aidenlab.org/shorten."
note "Until the key is set (next stages) /shorten answers with the long link, which is harmless."
if confirm "Deploy sw-shortlink now"; then
  npm run deploy:shortlink
else
  SKIPPED+=("deploy the worker: npm run deploy:shortlink")
  warn "skipped deploy; later stages will fail their checks"
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "TinyURL: create the new API key"
say "The old key shipped in every Spacewalk bundle, so the worker gets a fresh one."
say "The old key is revoked in the last stage, not now."
open_url "https://tinyurl.com/app/dev"
step "Sign in to the TinyURL account that owns the t.3dg.io domain."
step "On the Developer / API page, create a new API token. Name it 'sw-shortlink worker'."
step "Give it permission to create TinyURLs (and to use the t.3dg.io domain, if asked)."
step "Copy the token: TinyURL shows it only once."
note "If the page has moved, look for API / Developer under your account menu."
ask_secret NEW_TINYURL_API_KEY "Paste the new token (hidden):"
if [[ -z "$NEW_TINYURL_API_KEY" ]]; then
  warn "no token entered"
  SKIPPED+=("create a TinyURL token and run: cd $WORKER_DIR && npx wrangler secret put TINYURL_API_KEY")
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Cloudflare: store the key as the worker's secret"
say "Writes the token to sw-shortlink's TINYURL_API_KEY secret. It is not written to .env:"
say "only the worker needs it."
if [[ -n "${NEW_TINYURL_API_KEY:-}" ]]; then
  printf '%s' "$NEW_TINYURL_API_KEY" | (cd "$WORKER_DIR" && npx wrangler secret put TINYURL_API_KEY)
  printf '  %s✓ set%s worker secret TINYURL_API_KEY\n' "$GREEN" "$RESET"
else
  warn "no token from the previous stage; skipping"
fi
unset NEW_TINYURL_API_KEY
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Check: /shorten answers the app and refuses strangers"
check() {  # check "label" expected actual
  if [[ "$2" == "$3" ]]; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"
  else
    printf '  %s✗ %s%s (expected %s, got %s)\n' "$RED" "$1" "$RESET" "$2" "$3"
    CHECK_FAILED=1
  fi
}
CHECK_FAILED=0
preflight() {
  curl -s -o /dev/null -w '%{http_code}' -X OPTIONS "$SHORTEN" \
    -H "Origin: $1" -H "Access-Control-Request-Method: POST" -H "Access-Control-Request-Headers: content-type"
}
check "preflight from https://aidenlab.org is allowed" 204 "$(preflight https://aidenlab.org)"
check "preflight from a stranger is refused" 403 "$(preflight https://evil.example)"
short=$(curl -s -X POST "$SHORTEN" -H "Origin: https://aidenlab.org" -H "Content-Type: application/json" \
  --data '{"url":"https://aidenlab.org/spacewalk/?cutover-check=1"}')
case "$short" in
  *'"tiny_url":"https://t.3dg.io/'*) check "a real link is shortened on t.3dg.io" ok ok; note "  $short" ;;
  *) check "a real link is shortened on t.3dg.io" "a t.3dg.io link" "$short" ;;
esac
if (( CHECK_FAILED )); then
  warn "fix the failures before going on (npx wrangler tail, run from $WORKER_DIR, shows the worker's logs)"
  SKIPPED+=("checks against $SHORTEN failed; re-run this wizard once fixed")
  confirm "Continue anyway" || exit 1
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub: merge the client change, then drop the old key from builds"
say "The page now posts to the worker and carries no key."
step "Merge the share-url-shortlink-worker PR on aidenlab/spacewalk."
if command -v gh >/dev/null 2>&1; then
  open_url "$(gh pr view share-url-shortlink-worker --repo aidenlab/spacewalk --json url -q .url 2>/dev/null || echo https://github.com/aidenlab/spacewalk/pulls)"
fi
pause "Press Enter once the PR is merged"
say "Now remove TINYURL_API_KEY from Netlify: no build reads it any more."
open_url "https://app.netlify.com/projects/spacewalk-site/configuration/env"
step "Site configuration → Environment variables → TINYURL_API_KEY → Options → Delete."
pause "Press Enter once it is deleted"
if [[ -f .env ]] && grep -q '^TINYURL_API_KEY=' .env; then
  if confirm "Remove the now-unused TINYURL_API_KEY line from your local .env"; then
    tmp=$(mktemp); grep -v '^TINYURL_API_KEY=' .env > "$tmp" || true; mv "$tmp" .env
    printf '  %s✓ removed%s TINYURL_API_KEY from .env\n' "$GREEN" "$RESET"
  fi
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "TinyURL: revoke the old key"
say "The old key is readable in every Spacewalk bundle deployed before this change."
open_url "https://tinyurl.com/app/dev"
step "In the API token list, find the old Spacewalk token (not 'sw-shortlink worker')."
warn "Leave juicebox's token alone: jb-shortlink uses a different key on the same account."
if confirm "Have you identified the old token and want to revoke it now"; then
  step "Delete / revoke that token."
  pause "Press Enter once it is revoked"
else
  SKIPPED+=("revoke the old Spacewalk TinyURL token at https://tinyurl.com/app/dev")
fi

finish
